package jp.tapmarker;
public class CenterTapTest {
 static int n=0;static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);n++;System.out.println("PASS "+name);}
 static void reject(String text){try{PromptLogic.parse(text);throw new AssertionError("accepted contradictory prompt");}catch(IllegalArgumentException e){check(true,"conflicting center-tap instruction rejected");}}
 public static void main(String[] a){PromptLogic.Plan p=PromptLogic.parse("監視領域が変わったら監視領域中央をタップ。");check(p.action==6,"exact requested prompt interpreted");check(PromptLogic.parse("監視領域が変わったら監視領域の中央をタップ").action==6,"equivalent possessive wording interpreted");p=PromptLogic.parse("監視領域が変わったら監視領域中央をタップ。\n待機500ms。変化しきい値0.01");check(p.waitMs==500&&p.changeThreshold==.01f,"multiline wait and threshold interpreted");reject("監視領域が変わったら監視領域中央をタップ。マーカーを連打");reject("監視領域が変わったら監視領域中央をタップ。変化したら停止");ChangeTapDetector d=new ChangeTapDetector();float[] zero={0,0},small={.01f,.01f},larger={.04f,.04f},changed={.07f,.07f};check(!d.observe(zero,.004f),"initial frame registers baseline without tap");check(!d.observe(zero,.004f),"unchanged region does not trigger");check(!d.observe(small,.004f),"small noise does not trigger");check(!d.observe(larger,.004f),"subthreshold accumulated change waits");check(d.observe(changed,.004f),"accumulated region change triggers once");check(!d.observe(changed,.004f),"same changed frame does not repeat trigger");d.reset();check(!d.observe(new float[]{1,1},.004f),"post-tap first frame only rebaselines");float[] mutable={0,0};d.reset();d.observe(mutable,.004f);mutable[0]=1;check(d.observe(mutable,.004f),"baseline copied rather than aliased");float[] center=RegionMath.center(new float[]{.2f,.1f,.8f,.5f},1000,2000);check(center[0]==500&&center[1]==600,"tap uses monitor center rather than screen center");check(PromptLogic.parse("監視領域が変わったら監視領域中央をタップ。完了で停止").completionRequested,"optional taught completion stop interpreted");float[] other=RegionMath.center(new float[]{.6f,.6f,.9f,.9f},1000,2000);check(other[0]==750&&other[1]==1500,"second individual region uses its own center");check(center[0]!=other[0]&&center[1]!=other[1],"distinct regions never share one global center");System.out.println("TOTAL "+n+" center-tap checks passed; device gesture not tested.");}
}
